import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Kelviq Payment Gateway","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Kelviq Payment Gateway | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/kelviq"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Kelviq Payment Gateway | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/kelviq"}]]},"headers":[],"relativePath":"developer-guide/kelviq.md","filePath":"developer-guide/kelviq.md","lastUpdated":1794259478000}'),o={name:"developer-guide/kelviq.md"};function d(n,e,r,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="kelviq-payment-gateway" tabindex="-1">Kelviq Payment Gateway <a class="header-anchor" href="#kelviq-payment-gateway" aria-label="Permalink to &quot;Kelviq Payment Gateway&quot;">​</a></h1><p>Kelviq is a Central payment provider (Merchant of Record) that plugs into the existing gateway-agnostic billing stack. Business logic stays in <code>BillingEngine</code> / <code>ModuleSubscriptionService</code>; Kelviq only translates between Kelviq’s REST API and <code>PaymentGatewayInterface</code>.</p><p>Use Kelviq when EloSync SaaS Marketplace fees should be collected under an organization that Kelviq supports (for example Diligent Creators Private Limited in Pakistan) while Stripe entity setup is incomplete. Stripe, Creem, and Manual remain available; switch the <strong>default</strong> gateway in Central when ready.</p><p>Tenant workspaces accepting payments from <em>their</em> customers with workspace-owned keys use the free <strong>Payment Gateways</strong> module (<code>tenant_payment_gateway_connections</code>, including Kelviq). Do <strong>not</strong> reuse Central <code>payment_gateways</code> credentials for tenant CRM checkout — see <a href="/developer-guide/tenant-payment-gateways">Tenant Payment Gateways</a>.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BillingEngine → GatewayManager → PaymentGatewayInterface</span></span>
<span class="line"><span>                                      ├── ManualGateway</span></span>
<span class="line"><span>                                      ├── StripeGateway</span></span>
<span class="line"><span>                                      ├── CreemGateway</span></span>
<span class="line"><span>                                      └── KelviqGateway  (+ KelviqClient, KelviqWebhookVerifier)</span></span></code></pre></div><p>Do <strong>not</strong> add <code>kelviq_*</code> columns. The Kelviq <code>customerId</code> is the <strong>tenant UUID</strong>; it is also stored in provider-neutral <code>tenant_gateway_customers.customer_reference</code>. Plan mapping uses <code>payment_gateway_module_prices.gateway_product_reference</code> as the Kelviq <code>planIdentifier</code>.</p><p>Module access remains EloSync’s <code>workspace_module_subscriptions</code> (activated by webhooks). Kelviq entitlements / license keys are not used for Marketplace gating in v1.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Pull backend changes and run:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:seed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --class=Database\\\\Seeders\\\\Central\\\\PaymentGatewaySeeder</span></span></code></pre></div><ol start="2"><li><p>Configure credentials (env fallbacks <strong>or</strong> Central admin UI). Keep <code>KELVIQ_ENV=sandbox</code> until go-live.</p></li><li><p>Map billable modules under <strong>Billing → Payment Gateways → Product mapping</strong> — either click <strong>Sync catalog</strong> (creates/publishes Kelviq products + plans from EloSync prices and fills plan identifiers) or publish plans in the Kelviq dashboard and paste each <code>planIdentifier</code> manually.</p></li><li><p>Point Kelviq webhooks to <code>POST /webhooks/gateways/kelviq</code>.</p></li><li><p>Enable Kelviq and set it as the default gateway (only one default). Prefer <strong>Payment Gateways → Set as default</strong> over the Settings free-form field.</p></li></ol><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>KELVIQ_ENABLED</code></td><td>Seed row starts active when <code>true</code></td></tr><tr><td><code>KELVIQ_ENV</code></td><td><code>sandbox</code> (default) | <code>production</code> (seeded <code>mode</code> → sandbox/live)</td></tr><tr><td><code>KELVIQ_API_URL</code></td><td>Optional override (default sandbox/live Kelviq hosts)</td></tr><tr><td><code>KELVIQ_SERVER_API_KEY</code></td><td>Server API key fallback (<code>Authorization: Bearer</code>)</td></tr><tr><td><code>KELVIQ_WEBHOOK_SECRET</code></td><td>Signing secret (<code>kq_whsec_…</code>) for webhook verification</td></tr><tr><td><code>KELVIQ_TIMEOUT</code> / <code>KELVIQ_CONNECT_TIMEOUT</code></td><td>HTTP timeouts</td></tr></tbody></table><p>Prefer storing secrets in encrypted <code>payment_gateways.config</code> via the admin UI (<code>secret_key</code>, <code>webhook_secret</code>). Env values are fallbacks when the row is empty.</p><p>Config file: <code>config/kelviq.php</code>.</p><p>Never put production keys in sandbox mode. Do not change <code>KELVIQ_ENV</code> to <code>production</code> until business verification, live plans, and a production webhook are ready.</p><h2 id="sandbox-setup" tabindex="-1">Sandbox setup <a class="header-anchor" href="#sandbox-setup" aria-label="Permalink to &quot;Sandbox setup&quot;">​</a></h2><ol><li><p>Open Kelviq sandbox setup → copy Server API key (and later webhook secret) into Backend <code>.env</code> or Central <strong>Configure</strong>.</p></li><li><p>Central: enable Kelviq, mode <strong>sandbox</strong>, paste Server API key + Webhook secret.</p></li><li><p>Product mapping → <strong>Sync catalog</strong> (preferred) creates one Kelviq product/plan per EloSync module (<code>elosync-{slug}</code>), sets MONTHLY/YEARLY prices from catalog amounts, publishes the plan, and writes the plan identifier into both cycle rows. Or publish plans in the Kelviq dashboard and paste identifiers manually. Monthly / yearly rows share the plan identifier; checkout sends <code>chargePeriod</code> <code>MONTHLY</code> / <code>YEARLY</code>.</p><p>On the server you can also run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> payment-gateways:sync-catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kelviq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --overwrite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storage:verify-pack-mappings</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gateway=kelviq</span></span></code></pre></div><p><code>--gateway=kelviq</code> matches by gateway <strong>code</strong> (not driver class). If Sync writes <code>0</code> mappings, the CLI prints the first Kelviq API error per module.</p><p>Sync always upserts EloSync Product Mapping to <code>elosync-{slug}</code> after the Kelviq product/plan/prices exist. Publish is <strong>best-effort</strong>: already-<code>isLatest</code> plans are skipped, and publish HTML 500 / unpublished drafts do <strong>not</strong> block mapping (publish in the Kelviq dashboard if checkout requires a live plan).</p><p>The Central UI <strong>Sync catalog</strong> button queues <code>SyncPaymentGatewayCatalogJob</code> on the <code>catalog-sync</code> Horizon queue (up to ~10 minutes) and polls status — use it instead of waiting on a long HTTP request. The artisan command still runs sync inline for ops.</p></li><li><p>Register webhook URL (ngrok / Herd share / public API):</p></li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.elosync.com/webhooks/gateways/kelviq</span></span></code></pre></div><p>Subscribe at least: <code>checkout.completed</code>, <code>invoice.paid</code>, <code>invoice.payment_failed</code>, <code>subscription.created</code>, <code>subscription.updated</code>, <code>subscription.plan_changed</code>, <code>subscription.paused</code>, <code>subscription.resumed</code>, <code>subscription.cancelled</code>.</p><ol start="6"><li>Test connection → Set as default → purchase a billable module with a <a href="https://docs.kelviq.com/guides/sandbox.md" target="_blank" rel="noreferrer">sandbox test card</a>.</li></ol><h2 id="production-go-live-checklist" tabindex="-1">Production / go-live checklist <a class="header-anchor" href="#production-go-live-checklist" aria-label="Permalink to &quot;Production / go-live checklist&quot;">​</a></h2><ol><li>Complete Kelviq business verification and payouts for the collecting legal entity.</li><li>Publish <strong>production</strong> plans; remap live plan identifiers in Central.</li><li>Hosting secrets: production Server API key + webhook secret; set <code>KELVIQ_ENV=production</code> and gateway mode <strong>live</strong>.</li><li>Register production webhook: <code>https://api.elosync.com/webhooks/gateways/kelviq</code> with the same event set.</li><li>Sandbox end-to-end purchase must succeed before flipping the Central default to Kelviq live.</li><li>Keep Stripe/Creem enabled (not default) for a later provider switch if needed.</li></ol><h2 id="webhook-configuration" tabindex="-1">Webhook configuration <a class="header-anchor" href="#webhook-configuration" aria-label="Permalink to &quot;Webhook configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Endpoint</td><td><code>POST /webhooks/gateways/{code}</code> with <code>code=kelviq</code></td></tr><tr><td>Signature headers</td><td><code>webhook-id</code>, <code>webhook-timestamp</code>, <code>webhook-signature</code> (<code>v1,{hex}</code>)</td></tr><tr><td>Algorithm</td><td>HMAC-SHA256 over <code>{id}.{timestamp}.{rawBody}</code></td></tr><tr><td>Replay window</td><td>Reject when timestamp skew exceeds 300s (<code>KELVIQ_WEBHOOK_TOLERANCE_SECONDS</code>)</td></tr><tr><td>CSRF</td><td>Excepted (<code>webhooks/gateways/*</code>)</td></tr><tr><td>Idempotency</td><td><code>webhook_logs.provider_event_id</code> unique</td></tr></tbody></table><p>Invalid signatures → <code>400</code> and a failed webhook log.</p><h2 id="supported-events-mapping" tabindex="-1">Supported events &amp; mapping <a class="header-anchor" href="#supported-events-mapping" aria-label="Permalink to &quot;Supported events &amp; mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kelviq event</th><th>Normalized <code>GatewayEvent</code></th><th>Engine effect</th></tr></thead><tbody><tr><td><code>checkout.completed</code></td><td><code>payment_succeeded</code></td><td>Settle payment + activate pending module (subscription id may arrive later on <code>subscription.created</code>)</td></tr><tr><td><code>invoice.paid</code></td><td><code>payment_succeeded</code></td><td>Renewal / invoice settlement</td></tr><tr><td><code>invoice.payment_failed</code></td><td><code>payment_failed</code></td><td>Mark payment failed (failed renewal)</td></tr><tr><td><code>subscription.created</code></td><td><code>subscription_created</code></td><td>Link <code>provider_subscription_id</code></td></tr><tr><td><code>subscription.updated</code></td><td><code>subscription_updated</code></td><td>Sync (includes scheduled cancellation while still active)</td></tr><tr><td><code>subscription.plan_changed</code></td><td><code>subscription_updated</code></td><td>Sync plan change</td></tr><tr><td><code>subscription.paused</code></td><td><code>subscription_updated</code></td><td>Local status → <code>suspended</code>; entitlements cleared</td></tr><tr><td><code>subscription.resumed</code></td><td><code>subscription_updated</code></td><td>Local status → <code>active</code> when previously suspended</td></tr><tr><td><code>subscription.cancelled</code></td><td><code>subscription_cancelled</code></td><td>Cancel module when the subscription <strong>actually ends</strong> (not when cancellation is scheduled)</td></tr></tbody></table><p>See <a href="/deployment/kelviq-production-readiness">production readiness</a>.</p><h2 id="differences-vs-stripe-creem" tabindex="-1">Differences vs Stripe / Creem <a class="header-anchor" href="#differences-vs-stripe-creem" aria-label="Permalink to &quot;Differences vs Stripe / Creem&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Stripe</th><th>Creem</th><th>Kelviq</th></tr></thead><tbody><tr><td>SDK</td><td>Cashier + Stripe PHP</td><td>Laravel HTTP (<code>CreemClient</code>)</td><td>Laravel HTTP (<code>KelviqClient</code>)</td></tr><tr><td>Auth</td><td>Stripe secret</td><td><code>x-api-key</code></td><td>Bearer Server API key</td></tr><tr><td>Customer id</td><td><code>tenants.stripe_id</code></td><td>Creem <code>cust_…</code></td><td>Tenant UUID as Kelviq <code>customerId</code></td></tr><tr><td>Checkout reference</td><td><code>price_…</code></td><td><code>prod_…</code></td><td><code>planIdentifier</code> + <code>chargePeriod</code></td></tr><tr><td>Activation webhook</td><td><code>invoice.payment_succeeded</code></td><td><code>subscription.paid</code> / <code>checkout.completed</code></td><td><code>checkout.completed</code> (+ <code>subscription.created</code>)</td></tr><tr><td>Portal</td><td>Cashier</td><td>Creem billing link</td><td><code>\${customerPortalUrl}?token=…</code> (customer must have email)</td></tr></tbody></table><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KELVIQ_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KELVIQ_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sandbox</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KELVIQ_SERVER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KELVIQ_WEBHOOK_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:seed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --class=Database\\\\Seeders\\\\Central\\\\PaymentGatewaySeeder</span></span></code></pre></div><p>Forward Kelviq sandbox webhooks to <code>/webhooks/gateways/kelviq</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Central/Billing/KelviqGatewayTest.php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Central/Billing/KelviqWebhookTest.php</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Checkout fails “plan mapping missing”</td><td>Product mapping plan identifier for the default gateway</td></tr><tr><td>Signature failures</td><td>Raw body HMAC; headers <code>webhook-id</code> / <code>webhook-timestamp</code> / <code>webhook-signature</code>; secret matches endpoint</td></tr><tr><td>Portal 400</td><td>Customer must exist in Kelviq <strong>with an email</strong></td></tr><tr><td>Module not activating</td><td>Confirm <code>checkout.completed</code> webhook log <code>processed</code>; metadata includes payment / subscription ids</td></tr><tr><td>Wrong environment</td><td>Sandbox keys against live API (or reverse); keep <code>KELVIQ_ENV=sandbox</code> until go-live</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/developer-guide/payment-gateways-overview">Payment gateway architecture</a></li><li><a href="/developer-guide/payment-gateways">Developer guide</a></li><li><a href="/developer-guide/payment-gateways-webhooks">Webhooks</a></li><li><a href="/developer-guide/billing-engine">Billing Engine</a></li><li><a href="/developer-guide/creem">Creem gateway</a></li><li><a href="/developer-guide/stripe-cashier">Stripe / Cashier</a></li></ul>`,40)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
